// Grid — Gtk.Grid
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles grid with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface GridProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gint, from Gtk.Grid */
  baselineRow?: number

  /** gboolean, from Gtk.Grid */
  columnHomogeneous?: boolean

  /** gint, from Gtk.Grid */
  columnSpacing?: number

  /** gboolean, from Gtk.Grid */
  rowHomogeneous?: boolean

  /** gint, from Gtk.Grid */
  rowSpacing?: number
}

export function Grid({ className, children }: GridProps) {
  return (
    <div className={cn("pb-[3px]", "pl-[3px]", className)}>
      {children}
    </div>
  )
}
